#include <iostream>
#include <cmath>

void solve(long long n, long long p) {
    long long studied = 0;
    long long notStudied = n;

    long long zero;
    long long one;
    long long two;
    long long three;

    long long thisP;

    while (true) {
        zero = notStudied * (notStudied - 1) * (notStudied - 2) / 6;
        one = studied * notStudied * (notStudied - 1) / 2;
        two = studied * (studied - 1) * notStudied / 2;
        three = studied * (studied - 1) * (studied - 2) / 6;

        thisP = zero * 0 + one * 1 + two * 2 + three * 2;
        if (thisP * 5000 >= p * n * (n - 1) * (n - 2) / 6) {
            std::cout << studied << std::endl;
            return;
        }

        studied++;
        notStudied--;
    }
}

int main() {
    int n_input;
    double p_input;
    std::cin >> n_input >> p_input;
    long long n = n_input;
    long long p = static_cast<long long>(p_input * 10000);
    solve(n, p);
    return 0;
}
